use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Generate workspace Cargo.toml for extracted crates"] fn generate_workspace_toml (target_crate : & CrateInfo , all_crates : & HashSet < String > , dependency_graph : & HashMap < String , CrateInfo > ,) -> Result < String > { let mut toml = String :: new () ; toml . push_str (& format ! (r#"# Extracted Workspace for {}
# Generated by split-decls-rs extract tool
# Main crate: {}

[workspace]
resolver = "2"
members = [
"# , target_crate . name , target_crate . name)) ; for crate_name in all_crates { toml . push_str (& format ! ("    \"{}\",\n" , crate_name)) ; } toml . push_str ("]\n\n") ; toml . push_str (r#"[workspace.package]
edition = "2024"
version = "0.1.0"
authors = ["Split-Decls-RS Extract Tool"]
license = "MIT OR Apache-2.0"
description = "Extracted standalone workspace"
repository = "https://github.com/your-org/extracted-workspace"

[workspace.lints]
# Workspace-level lints

"#) ; toml . push_str ("[workspace.dependencies]\n") ; let mut all_deps = HashSet :: new () ; for crate_info in dependency_graph . values () { all_deps . extend (& crate_info . dependencies) ; all_deps . extend (& crate_info . dev_dependencies) ; } for dep in & all_deps { if all_crates . contains (& format ! ("wrapped-{}" , dep)) { toml . push_str (& format ! ("{} = {{ path = \"wrapped-{}\" }}\n" , dep , dep)) ; } else { toml . push_str (& format ! ("{} = \"*\"\n" , dep)) ; } } Ok (toml) }
}